package com.perkvault.app;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.provider.Settings;import android.animation.ValueAnimator;
public class Bubble extends Service {
 WindowManager wm; TextView bubble,target; WindowManager.LayoutParams p,q; boolean open=false,drag=false,magnet=false; long down; ValueAnimator anim; int size; float x,y; int px,py;
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);} int width(){return getResources().getDisplayMetrics().widthPixels;} int height(){return getResources().getDisplayMetrics().heightPixels;}
 GradientDrawable circle(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setShape(GradientDrawable.OVAL);return d;}
 public IBinder onBind(Intent i){return null;}
 WindowManager.LayoutParams params(int s){WindowManager.LayoutParams a=new WindowManager.LayoutParams(s,s,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);a.gravity=Gravity.TOP|Gravity.LEFT;return a;}
 TextView chip(String text,int color){TextView v=new TextView(this);v.setText(text);v.setTextColor(Color.WHITE);v.setTextSize(26);v.setGravity(Gravity.CENTER);v.setBackground(circle(color));v.setElevation(dp(6));return v;}
 public int onStartCommand(Intent i,int flags,int id){if(i!=null&&"stop".equals(i.getAction())){stopSelf();return START_NOT_STICKY;}if(!Settings.canDrawOverlays(this)){stopSelf();return START_NOT_STICKY;}NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("bubble","Floating shortcut",NotificationManager.IMPORTANCE_LOW));PendingIntent stop=PendingIntent.getService(this,3,new Intent(this,Bubble.class).setAction("stop"),PendingIntent.FLAG_IMMUTABLE);startForeground(1,new Notification.Builder(this,"bubble").setSmallIcon(android.R.drawable.ic_menu_save).setContentTitle("PerkVault shortcut active").setContentText("Drag to × to close. Stop before payments.").addAction(new Notification.Action.Builder(null,"Stop",stop).build()).build());if(bubble!=null)return START_NOT_STICKY;
 wm=getSystemService(WindowManager.class);size=dp(64);bubble=chip("%",0xffdfff65);bubble.setTextColor(0xff143b2d);bubble.setContentDescription("Save voucher");p=params(size);p.x=getSharedPreferences("bubble",0).getInt("x",width()-size);p.y=getSharedPreferences("bubble",0).getInt("y",height()/3);clamp();bubble.setOnTouchListener((v,e)->{switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:if(anim!=null)anim.cancel();x=e.getRawX();y=e.getRawY();px=p.x;py=p.y;drag=false;magnet=false;down=SystemClock.uptimeMillis();return true;case MotionEvent.ACTION_MOVE:if(!drag&&Math.hypot(e.getRawX()-x,e.getRawY()-y)>ViewConfiguration.get(this).getScaledTouchSlop()){drag=true;showTarget();}if(drag){p.x=px+Math.round(e.getRawX()-x);p.y=py+Math.round(e.getRawY()-y);clamp();if(near()){if(!magnet){target.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);magnet=true;}p.x=q.x+(q.width-size)/2;p.y=q.y+(q.height-size)/2;target.setBackground(circle(0xffb42318));}else {magnet=false;target.setBackground(circle(0xff424242));}wm.updateViewLayout(bubble,p);}return true;case MotionEvent.ACTION_UP:if(drag){boolean close=near();hideTarget();if(close){stopSelf();return true;}snap();}else if(SystemClock.uptimeMillis()-down>500){Intent launch=new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(launch);}else if(!open){open=true;try{Capture.show(this,"",()->open=false);}catch(Exception ex){open=false;Toast.makeText(this,"Open PerkVault to save",0).show();}}return true;case MotionEvent.ACTION_CANCEL:hideTarget();snap();return true;}return false;});wm.addView(bubble,p);return START_NOT_STICKY;}
 void clamp(){p.x=Math.max(0,Math.min(width()-size,p.x));p.y=Math.max(0,Math.min(height()-size-dp(48),p.y));}
 void showTarget(){if(target!=null)return;target=chip("×",0xff424242);q=params(dp(76));q.flags|=WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE;q.x=(width()-q.width)/2;q.y=height()-q.height-dp(72);wm.addView(target,q);}
 boolean near(){return target!=null&&Math.hypot(p.x+size/2f-q.x-q.width/2f,p.y+size/2f-q.y-q.height/2f)<dp(64);}
 void hideTarget(){if(target!=null){wm.removeView(target);target=null;}}
 void snap(){int end=p.x+size/2<width()/2?0:width()-size;anim=ValueAnimator.ofInt(p.x,end);anim.setDuration(180);anim.addUpdateListener(a->{if(bubble!=null){p.x=(Integer)a.getAnimatedValue();wm.updateViewLayout(bubble,p);}});anim.start();getSharedPreferences("bubble",0).edit().putInt("x",end).putInt("y",p.y).apply();}
 public void onDestroy(){if(anim!=null)anim.cancel();hideTarget();if(bubble!=null){wm.removeView(bubble);bubble=null;}super.onDestroy();}
}
